make_complexJ(OPT_COMPLEXJ) := block(
  if OPT_COMPLEXJ = "i" then
    (texput(%i,"\\mathrm{i}"))
  else if OPT_COMPLEXJ = "j" then
    (kill(i),%j:%i,j:%i,texput(%i,"\\mathrm{j}"))
  else if OPT_COMPLEXJ = "symi" then
    (kill(i),texput(%i,"\\mathrm{i}"))
  else if OPT_COMPLEXJ = "symj" then
    (kill(i),texput(%i,"\\mathrm{j}"))
  else true
)$

/* Choose the symbol for the multiplication sign. */
make_multsgn(OPT_MULTSGN) := block(
    if ev(not(elementp(OPT_MULTSGN, {"cross", "dot", "onum", "none", "space"})), simp)
        then error("make_multsgn received un-supported option: ", OPT_MULTSGN),
    if OPT_MULTSGN = "cross" then (texput("*", "\\times ", nary),
                                   texput("nounmul", "\\times ", nary)),
    if OPT_MULTSGN = "dot" then (texput("*", "\\cdot ", nary),
                                   texput("nounmul", "\\cdot ", nary)),
    if OPT_MULTSGN = "onum" then (texput("*", multsgnonlyfornumbers),
                                   texput("nounmul", multsgnonlyfornumbers)),
    if OPT_MULTSGN = "none" then (texput("*", " ", nary),
                                   texput("nounmul", " ", nary)),
    if OPT_MULTSGN = "space" then (texput("*", "\\,", nary),
                                   texput("nounmul","\\,", nary))
);

/* This only prints a multiplication sign for numbers. */
/* Thanks to Evgeniy Silchenko.                        */
texput(multsgnonlyfornumberssym, "\\times")$

multsgnonlyfornumbers(e) := block([arglist, resstr, a, lastisnum, isnum, multsgn, str],
    arglist: args(e),
    a: pop(arglist),
    resstr: if ev(is(safe_op(a) = "-" or (real_numberp(a) and is(a<0)))=true, simp) then sconcat("\\left(", tex1(a), "\\right)")
                else if (atom(a) or is(length(args(a))=1) or safe_op(a) = "^") or rational_numberp(a) then tex1(a)
                else sconcat("\\left(", tex1(a), "\\right)"),
    lastisnum: real_numberp(a),
    for a in arglist do (
        isnum: real_numberp(a),
        multsgn: if ev(is(lastisnum and isnum)=true, simp) then tex1(multsgnonlyfornumberssym) else "\\,",
        str: if is(safe_op(a)="-") or ((integerp(a) or floatnump(a)) and ev(is(a<0)=true, simp)) then sconcat("\\left(", tex1(a), "\\right)")
                else if atom(a) or is(length(args(a))=1) or is(safe_op(a)= "^") or rational_numberp(a) then tex1(a)
                else sconcat("\\left(", tex1(a), "\\right)"),
        resstr: sconcat(resstr, multsgn, " ", str),
        lastisnum: isnum
    ),
    resstr
)$

make_logic(OPT_LOGIC) := block(
    if OPT_LOGIC = "lang" then block(
        texput("and", "\\,{\\text{ !AND! }}\\, ", nary),
        texput("nounand", "\\,{\\text{ !AND! }}\\, ", nary),
        texput("or", "\\,{\\text{ !OR! }}\\, ", nary),
        texput("nounor", "\\,{\\text{ !OR! }}\\, ", nary),
        texput("nand", "\\,{\\text{ !NAND! }}\\, ", nary),
        texput("nor", "\\,{\\text{ !NOR! }}\\, ", nary),
        texput("xor", "\\,{\\text{ !XOR! }}\\, ", nary),
        texput("xnor", "\\,{\\text{ !XNOR! }}\\, ", nary),
        texput("implies", "\\,{\\text{ !IMPLIES! }}\\, ", nary),
        texput("not", "{\\rm !NOT!}", prefix),
        texput("nounnot", "{\\rm !NOT!}", prefix)
    ),
    if OPT_LOGIC = "symbol" then block(
        texput("and", "\\land ", nary),
        texput("nounand", "\\land ", nary),
        texput("or", "\\lor ", nary),
        texput("nounor", "\\lor ", nary),
        texput("nand", "\\overline{\\land}", nary),
        texput("nor", "\\underline{\\lor}", nary),
        texput("xor", "\\oplus ", nary),
        texput("xnor", "\\leftrightarrow ", nary),
        texput("implies", "\\rightarrow ", nary),
        texput("not", "\\neg ", prefix),
        texput("nounnot", "\\neg ", prefix)
    ),
    return(true)
)$

